int twice(int n) {
  return n + n;
}

int main() {
  return twice(6);
}

int main() {
  int i; int sum;
  i = 0; sum = 0;
  while (i < 3) {
    sum = sum + i * 2;
    i = i + 1;
  }
  return sum;
}

void main() {
  int x;
  x = 1;
  {
    int x;
    x = 2;
    print_i(x);
  }
  print_i(x);
}

void main() {
  int first;
  int second;
  int next;
  int i;
  first = 0;
  second = 1;
  i = 0;
  while (i < 10) {
    print_i(first);
    print_s((char*)" ");
    next = first + second;
    first = second;
    second = next;
    i = i + 1;
  }
}

void main() {
  int i;
  i = 0;
  while (i < 10) {
    i = i + 1;
    if (i == 5) {
      continue;
    }
    if (i == 8) {
      break;
    }
    print_i(i);
  }
}

void main() {
  int x;
  int* p;
  x = 42;
  p = &x;
  *p = *p + 1;
  print_i(x);
}

struct Point {
  int x;
  int y;
};

int main() {
  struct Point p;
  p.x = 10;
  p.y = 20;
  return p.x + p.y;
}

